// Functions receive shared services and state through an explicit application context.
export function install(ctx){
function listPage(type){const c=type==='clients',data=c?ctx.clients:ctx.products;ctx.shell(`${ctx.head(c?'Clientes':'Produtos',c?'Cada relacionamento começa com um bom cadastro.':'Seu catálogo, seus custos e seus preços em um só lugar.',c?'client-new':'product-new',c?'Cadastrar cliente':'Cadastrar produto')}${ctx.profile?.is_owner?'<div class="toolbar"><button class="secondary small" id="import-registers">Importar planilha</button></div>':''}<section class="panel"><div class="panelhead"><h2>${c?'Lista de clientes':'Catálogo de produtos'} <span class="badge">${data.length} registros</span></h2><input id="search" aria-label="Buscar ${c?'cliente':'produto'}" placeholder="Buscar por nome…" type="search"></div><div id="rows"></div></section>`);function draw(s=''){const list=data.filter(x=>(x.name+' '+(x.document||x.sku||'')+' '+(x.reference||'')).toLowerCase().includes(s.toLowerCase()));ctx.$('#rows').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr>${(c?['Cliente','Tipo','CPF / CNPJ','Telefone','E-mail','Ações']:['Produto','Código','Custo','Varejo','Atacado','Ações']).map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${list.map(x=>c?`<tr><td><strong>${ctx.esc(x.name)}</strong></td><td><span class="badge">${x.kind}</span></td><td>${ctx.esc(x.document)||'—'}</td><td>${ctx.esc(x.phone)||'—'}</td><td>${ctx.esc(x.email)||'—'}</td>${recordButtons(type,x)}</tr>`:`<tr><td><strong>${ctx.esc(x.name)}</strong></td><td>${ctx.esc(x.sku)||'—'}</td><td>${ctx.money(x.cost)}</td><td>${ctx.money(x.retail)}</td><td>${ctx.money(x.wholesale)}</td>${recordButtons(type,x)}</tr>`).join('')}</tbody></table></div>`:ctx.empty(s?'Nenhum resultado encontrado.':c?'Seu primeiro cliente tem lugar aqui.':'Vamos montar seu catálogo?',s?'Tente outro nome.':'Use o botão acima para cadastrar.');bindRecordActions(type,list)}draw();ctx.$('#import-registers')?.addEventListener('click',()=>ctx.registerImportDialog(type));ctx.$('#search').oninput=e=>draw(e.target.value)}

function formPage(page){const c=page==='client-new';ctx.shell(`${ctx.head(c?'Cadastrar cliente':'Cadastrar produto',c?'Dados organizados para propostas mais completas.':'Defina o custo e os preços de referência do produto.')}<section class="panel"><form class="panelbody" id="record-form"><div class="grid2">${c?`<label class="field">Tipo de cliente<select name="kind"><option value="PF">Pessoa física (PF)</option><option value="PJ">Pessoa jurídica (PJ)</option></select></label>${ctx.field('Nome / Razão social','name','text','','required minlength="2" maxlength="200"')}${ctx.field('CPF / CNPJ','document','text','','maxlength="20"')}${ctx.field('Telefone / WhatsApp','phone','tel','','maxlength="25"')}${ctx.field('E-mail','email','email','','maxlength="200"')}${ctx.field('Endereço','address','text','','maxlength="500"')}`:`${ctx.field('Nome do produto','name','text','','required minlength="2" maxlength="200"')}<label class="field">Código automático<input value="Gerado automaticamente ao salvar" disabled></label>${ctx.field('Referência interna (opcional)','reference','text','','maxlength="80"')}<div class="span2 grid3">${ctx.field('Custo unitário (R$)','cost','number','','required min="0" max="9999999999" step="0.01"')}${ctx.field('Preço de varejo (R$)','retail','number','','required min="0" max="9999999999" step="0.01"')}${ctx.field('Preço de atacado (R$)','wholesale','number','','required min="0" max="9999999999" step="0.01"')}</div><p class="note span2">Os orçamentos calculam o preço a partir do custo e do percentual escolhido. O orçamento permite ajustar o preço de cada item e conferir a margem resultante. Varejo e atacado ficam como referências do catálogo.</p>`}</div><p id="form-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" id="cancel">Cancelar</button><button type="submit" class="primary">Salvar ${c?'cliente':'produto'}</button></div></form></section>`);if(c)ctx.addDocumentLookup(ctx.$('#record-form'),{type:'clients'});ctx.$('#cancel').onclick=()=>ctx.render(c?'clients':'products');ctx.$('#record-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const body=Object.fromEntries(new FormData(e.target));if(c&&ctx.existingDocument('clients',body.document)){ctx.$('#form-error').textContent='Este CPF/CNPJ já está cadastrado. Localize o cliente e use Editar.';e.submitter.disabled=false;return}if(!c)for(const k of ['cost','retail','wholesale'])body[k]=Number(body[k]);try{await ctx.api('/rest/v1/'+(c?'clients':'products'),{method:'POST',body,headers:{Prefer:'return=representation'}});await ctx.load();ctx.toast(c?'Cliente cadastrado com sucesso.':'Produto cadastrado com sucesso.');ctx.render(c?'clients':'products')}catch(err){ctx.$('#form-error').className='error';ctx.$('#form-error').textContent=err.message;e.submitter.disabled=false}}}

function recordButtons(type,x){return '<td class="nowrap">'+(ctx.can(type,'edit')?'<button class="secondary small" data-edit="'+x.id+'">Editar</button> ':'')+(ctx.can(type,'delete')?'<button class="danger small" data-delete="'+x.id+'">Excluir</button>':'')+'</td>'}
function bindRecordActions(type,list){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editRecord(type,list.find(x=>x.id===b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir este cadastro? Cadastros vinculados a orçamentos serão preservados.'))return;b.disabled=true;try{await ctx.api('/rest/v1/'+type+'?id=eq.'+b.dataset.delete,{method:'DELETE'});await ctx.load();ctx.render(type);ctx.toast('Cadastro excluído.')}catch(e){ctx.toast(e.message.includes('foreign key')?'Este cadastro está vinculado a um orçamento e deve ser preservado.':e.message);b.disabled=false}})}
function editRecord(type,record){if(!record||!ctx.can(type,'edit'))return;const c=type==='clients',d=document.createElement('dialog');d.style.width='min(650px,95vw)';d.innerHTML='<h2>Editar '+(c?'cliente':'produto')+'</h2><form id="edit-record"><div class="grid2">'+(c?'<label class="field">Tipo<select name="kind"><option value="PF" '+(record.kind==='PF'?'selected':'')+'>Pessoa física</option><option value="PJ" '+(record.kind==='PJ'?'selected':'')+'>Pessoa jurídica</option></select></label>'+ctx.field('Nome / Razão social','name','text',record.name,'required minlength="2" maxlength="200"')+ctx.field('CPF / CNPJ','document','text',record.document,'maxlength="20"')+ctx.field('Telefone','phone','tel',record.phone,'maxlength="25"')+ctx.field('E-mail','email','email',record.email,'maxlength="200"')+ctx.field('Endereço','address','text',record.address,'maxlength="500"'):ctx.field('Nome do produto','name','text',record.name,'required minlength="2" maxlength="200"')+ctx.field('Código automático','sku','text',record.sku,'disabled')+ctx.field('Referência interna (opcional)','reference','text',record.reference||'','maxlength="80"')+['cost','retail','wholesale'].map((k,i)=>ctx.field(['Custo (R$)','Varejo (R$)','Atacado (R$)'][i],k,'number',record[k],'required min="0" max="9999999999" step="0.01"')).join(''))+'</div><p class="note">Orçamentos já emitidos preservam seus dados e preços originais.</p><p id="edit-error" role="alert"></p><div class="form-actions"><button class="secondary" type="button" id="cancel-edit">Cancelar</button><button class="primary" type="submit">Salvar alterações</button></div></form>';document.body.append(d);d.showModal();if(c)ctx.addDocumentLookup(d.querySelector('form'),{type:'clients'});ctx.$('#cancel-edit').onclick=()=>d.close();d.onclose=()=>d.remove();ctx.$('#edit-record').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const body=Object.fromEntries(new FormData(e.target));if(!c)for(const k of ['cost','retail','wholesale'])body[k]=Number(body[k]);try{await ctx.api('/rest/v1/'+type+'?id=eq.'+record.id,{method:'PATCH',body,headers:{Prefer:'return=representation'}});await ctx.load();d.close();ctx.render(type);ctx.toast('Cadastro atualizado.')}catch(err){ctx.$('#edit-error').textContent=err.message;e.submitter.disabled=false}}}

Object.assign(ctx,{listPage,formPage});
}
